    // Peeks never add Undo steps. One Undo removes exactly the author's one edit.
    p.operation(json!({"type":"command","command":"undo"}),true);wait(||p.pending.get()==0);assert_eq!(p.frame.borrow()["document"],rich["document"]);p.operation(json!({"type":"command","command":"redo"}),true);wait(||p.pending.get()==0);assert_eq!(p.frame.borrow()["document"],document);
