    wait(||a.peek.visible()&&a.peek.text().contains("Authored نور 明"));
    assert!(a.window.emit_by_name::<bool>("key-release-event",&[&*key(f6,true)]));
    assert!(!a.peek.visible());
    press(&p,f7);wait(||a.peek.visible());
    assert!(a.window.emit_by_name::<bool>("key-release-event",&[&*key(f6,true)]));
    assert!(a.peek.visible());
    assert!(p.area.emit_by_name::<bool>("key-release-event",&[&*key(f7,true)]));
    assert!(!a.peek.visible());
    press(&p,f6);wait(||a.peek.visible());
    let mut outside=gdk::Event::new(gdk::EventType::FocusChange);
    outside.downcast_mut::<gdk::EventFocus>().unwrap().as_mut().in_=0;
    a.window.emit_by_name::<bool>("focus-out-event",&[&outside]);
