    let peer_data=fixture.path().join("peek-peer-data");std::fs::create_dir_all(&peer_data).unwrap();let peer=Process::start(&binaries.join(companion),&peer_data,true).unwrap();let remote=rpc(&child.client,"sync_cursor",json!({}));let local=rpc(&peer,"sync_cursor",json!({}));let revisions=rpc(&child.client,"pull_revisions",json!({"projectId":pid,"cursor":{"epoch":remote["epoch"],"sequence":0},"limit":100}));rpc(&peer,"ingest_revisions",json!({"projectId":pid,"expectedEpoch":local["epoch"],"remoteEpoch":remote["epoch"],"manifest":rpc(&child.client,"open_project",json!({"projectId":pid})),"revisions":revisions["revisions"]}));
    let planning=rpc(&child.client,"load_project_data",json!({"projectId":pid,"kind":"planning"}));let mut primary=planning["payload"].clone();primary["records"][0]["notes"]=json!("Primary author's competing note");let mut other=planning["payload"].clone();other["records"][0]["notes"]=json!("Peer author's competing note");rpc(&child.client,"save_project_data",json!({"projectId":pid,"kind":"planning","payload":primary,"parent":planning["revisionId"]}));rpc(&peer,"save_project_data",json!({"projectId":pid,"kind":"planning","payload":other,"parent":planning["revisionId"]}));let peer_cursor=rpc(&peer,"sync_cursor",json!({}));let local=rpc(&child.client,"sync_cursor",json!({}));let revisions=rpc(&peer,"pull_revisions",json!({"projectId":pid,"cursor":{"epoch":peer_cursor["epoch"],"sequence":0},"limit":100}));rpc(&child.client,"ingest_revisions",json!({"projectId":pid,"expectedEpoch":local["epoch"],"remoteEpoch":peer_cursor["epoch"],"manifest":rpc(&peer,"open_project",json!({"projectId":pid})),"revisions":revisions["revisions"]}));
